package net.officefloor.hq.app.claim;

/**
 * A claim with a negative amount is a correction: allowed only when it names, by number, a SETTLED claim of the same
 * person that it corrects. Any other claim corrects nothing (a number given with it is not kept).
 */
public final class Corrections {

    private Corrections() {
    }

    /** The number the claim with these values corrects (null when it is not a correction); a correction that does
     *  not name a SETTLED claim of the person is refused. */
    public static String check(String sheetId, long personId, ClaimValues values, ClaimRepository claims)
            throws InvalidClaimException {
        if (values.amount().signum() >= 0) {
            return null;
        }
        if (values.corrects() == null) {
            throw new InvalidClaimException("A negative amount must name the settled claim it corrects");
        }
        Claim corrected = claims.findByNumber(sheetId, personId, values.corrects());
        if (corrected == null || corrected.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimException("A correction must name a settled claim of the same person");
        }
        return values.corrects();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Writes a claim's status log: once the claim is stored with its new status (DRAFT when added), a line with that
 * status, who made the change, the sheet's today, and the claim's due as the screen shows it at that moment (its
 * figure with its late charge, see ClaimDue and LateCharge; n/a when it has none).
 */
@Service
public class ClaimLog {

    private final ClaimLogRepository log;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public ClaimLog(ClaimLogRepository log, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        this.log = log;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    public void write(Claim claim, String by) {
        String sheetId = claim.sheetId();
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        Person person = people.find(sheetId, claim.personId());
        BigDecimal figure = person == null ? claim.due()
                : late.add(claim, ClaimDue.figure(claim, person.gradeOn(claim.date()), rates, settings.floor(sheetId, claim.date()),
                        late.rounding()));
        log.add(sheetId, new ClaimLogLine(claim.id(), claim.status(), by, late.today(),
                figure == null ? "n/a" : figure.toPlainString()));
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/** The claim is dated the sheet's today, which may not be inside a closed period. Checked before a new person is
 *  added, so a refused claim leaves no person and no audit record behind. */
public class CheckQuickAddDate {
    public void check(@PathVariable("sheetId") String sheetId, SheetRepository sheets, PeriodRepository periods)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        if (periods.closedOn(sheet, sheets.today(sheet))) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
    }
}
